"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Check } from "@/components/ui/icons";

// Menu Item: generated by UIX from the design system. Same variants and sizes as the Figma component.

const menuItemVariants = cva(
  "flex w-full cursor-pointer items-center text-left outline-none transition-colors h-[36px] px-3 gap-[10px] rounded-sm text-body-medium disabled:pointer-events-none disabled:text-fg-disabled [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary",
  {
    variants: {
      type: {
        default: "text-fg-primary hover:bg-subtle focus-visible:bg-subtle",
        destructive: "text-fg-danger hover:bg-danger-subtle focus-visible:bg-danger-subtle [&_svg]:text-icon-danger",
      },
    },
    defaultVariants: {
      type: "default",
    },
  },
);

export interface MenuProps
  extends React.HTMLAttributes<HTMLDivElement> {}

const Menu = React.forwardRef<HTMLDivElement, MenuProps>(
  ({ className, onKeyDown, ...props }, ref) => (
    <div data-slot="menu" data-kind="overlay" ref={ref} role="menu" className={cn("flex flex-col p-1 gap-0-5 bg-surface border border-line-default rounded-md shadow-lg", className)} onKeyDown={(event) => {
      onKeyDown?.(event);
      const items = Array.from(event.currentTarget.querySelectorAll<HTMLElement>('[role^="menuitem"]:not(:disabled)'));
      const index = items.indexOf(document.activeElement as HTMLElement);
      const next = event.key === "ArrowDown" ? (index + 1) % items.length : event.key === "ArrowUp" ? (index - 1 + items.length) % items.length : event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : -1;
      if (next < 0) return;
      event.preventDefault();
      items[next]?.focus();
    }} {...props} />
  ),
);
Menu.displayName = "Menu";

export interface MenuItemProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "type">, VariantProps<typeof menuItemVariants> {
  /** Icon before the label. */
  icon?: React.ReactNode;
  /** Avatar before the label. */
  leadingAvatar?: React.ReactNode;
  /** Hint at the end, for example ⌘S. */
  shortcut?: React.ReactNode;
  /** Turns the item into a checkbox item and sets its state. */
  checked?: boolean;
}

const MenuItem = React.forwardRef<HTMLButtonElement, MenuItemProps>(({ className, type, icon, leadingAvatar, shortcut, checked, children, ...props }, ref) => (
  <button ref={ref} type="button" role={checked === void 0 ? "menuitem" : "menuitemcheckbox"} aria-checked={checked} data-slot="menu-item" className={cn(menuItemVariants({ type }), className)} {...props}>
    {checked === void 0 ? null : (
      <span aria-hidden aria-checked={checked} className="inline-flex shrink-0 items-center justify-center border size-4 rounded-sm border-line-strong bg-surface [&[aria-checked=true]]:bg-brand [&[aria-checked=true]]:text-fg-on-brand [&[aria-checked=true]]:border-transparent">
        {checked ? <Check /> : null}
      </span>
    )}
    {leadingAvatar}
    {icon}
    <span className="min-w-0 flex-1 truncate">{children}</span>
    {shortcut ? <span className="text-body-small text-fg-tertiary">{shortcut}</span> : null}
  </button>
));
MenuItem.displayName = "MenuItem";

const MenuSeparator = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} role="separator" className={cn("my-1 h-px bg-line-subtle", className)} {...props} />
));
MenuSeparator.displayName = "MenuSeparator";

export { Menu, MenuItem, MenuSeparator, menuItemVariants };
